// Compiles juno.dsp to WebAssembly and writes juno-dsp.js, which embeds the
// result so the UI also works when opened straight from disk (file://).
// Also refreshes ../vendor/faustwasm.js, the browser runtime from @grame/faustwasm.
//
//   cd Juno/dsp && npm install && npm run build

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const fw = path.join(here, 'node_modules', '@grame', 'faustwasm');
const out = path.join(here, '.build');
const vendor = path.join(here, '..', 'vendor');

fs.rmSync(out, { recursive: true, force: true });
execFileSync(process.execPath, [path.join(fw, 'scripts', 'faust2wasm.js'), path.join(here, 'juno.dsp'), out, '-poly', '-no-template'], { stdio: 'inherit' });

const b64 = f => fs.readFileSync(path.join(out, f)).toString('base64');
const meta = fs.readFileSync(path.join(out, 'dsp-meta.json'), 'utf8');
fs.writeFileSync(path.join(here, 'juno-dsp.js'),
  '// Generated by dsp/build.mjs from juno.dsp. Do not edit by hand.\n' +
  `window.JUNO_DSP = {\n  meta: ${meta.trim()},\n  dsp: "${b64('dsp-module.wasm')}",\n  mixer: "${b64('mixer-module.wasm')}",\n` +
  `  effectMeta: ${fs.readFileSync(path.join(out, 'effect-meta.json'), 'utf8').trim()},\n  effect: "${b64('effect-module.wasm')}"\n};\n`);

// Browser build of faustwasm is an IIFE without exports; expose the two generators.
let src = fs.readFileSync(path.join(fw, 'dist', 'cjs', 'index.js'), 'utf8');
const end = /\}\)\(\);\s*\/\/# sourceMappingURL=index\.js\.map\s*$/;
if (!end.test(src)) throw new Error('faustwasm layout changed: cannot expose FaustWasm global');
src = src.replace(end, '  window.FaustWasm = { FaustMonoDspGenerator, FaustPolyDspGenerator };\n})();\n');
const version = JSON.parse(fs.readFileSync(path.join(fw, 'package.json'), 'utf8')).version;
fs.mkdirSync(vendor, { recursive: true });
fs.writeFileSync(path.join(vendor, 'faustwasm.js'),
  `// @grame/faustwasm ${version} browser runtime (LGPL-2.1, see faustwasm-COPYING.txt).\n// Copied by dsp/build.mjs; only change: exposes window.FaustWasm.\n` + src);
fs.copyFileSync(path.join(fw, 'COPYING.txt'), path.join(vendor, 'faustwasm-COPYING.txt'));
console.log('Wrote dsp/juno-dsp.js and vendor/faustwasm.js');
